use xiom.io;

use xiom.string;
fn grade_answer(question: Str, answer: Str, correct: Str) -> Result[Bool, Str] {
  if string.str_len(answer) == 0 {
    return Err("Answer cannot be empty");
  }
  return Ok(answer == correct);
}

fn main() -> Int {
  var score = 0;
  match grade_answer("Capital of France", "Paris", "Paris") {
    Ok(true) => { score = score + 1; }
    Ok(false) => { }
    Err(_) => { }
  }
  match grade_answer("2 + 2", "4", "4") {
    Ok(true) => { score = score + 1; }
    Ok(false) => { }
    Err(_) => { }
  }
  match grade_answer("Color of sky", "blue", "blue") {
    Ok(true) => { score = score + 1; }
    Ok(false) => { }
    Err(_) => { }
  }
  return score * 100;
}
